class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);window.statusBarColor=android.graphics.Color.rgb(250,247,255);window.navigationBarColor=android.graphics.Color.rgb(250,247,255);window.decorView.systemUiVisibility=0x00002000 or 0x00000010;setContent{App()}}}
private val ink=Color(0xFF25213A);private val pink=Color(0xFFE95B91);private val blue=Color(0xFF5B82E8);private val palette=listOf(Color(0xFFE95B91),Color(0xFF65B978),Color(0xFFF2C34E),Color(0xFF5B82E8))
@Composable fun App(){var page by remember{mutableStateOf(0)};var mode by remember{mutableStateOf("LOCAL")};var dice by remember{mutableIntStateOf(6)};var turn by remember{mutableIntStateOf(0)};var moves by remember{mutableIntStateOf(0)};MaterialTheme(colorScheme=lightColorScheme(primary=pink,background=Color(0xFFFFF9F2))){Surface(Modifier.fillMaxSize(),color=Color(0xFFFFF9F2)){when(page){0->Home({mode=it;page=1});1->Setup(mode,{page=0},{page=2});else->Game(dice,turn,moves,{dice=Random.nextInt(1,7);turn=(turn+1)%4},{moves++},{page=0})}}}}
@Composable fun Home(play:(String)->Unit){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Spacer(Modifier.height(22.dp));Row(verticalAlignment=Alignment.CenterVertically){Text("ZXH",color=pink,fontWeight=FontWeight.Black,fontSize=18.sp);Text(" OFFICIAL",color=ink,fontWeight=FontWeight.Black,fontSize=18.sp);Spacer(Modifier.weight(1f));Text("FREE • OFFLINE",color=blue,fontSize=10.sp,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(24.dp));Text("LUDO",fontSize=48.sp,fontWeight=FontWeight.Black,color=ink,letterSpacing=4.sp);Text("PLAY • ROLL • WIN",fontSize=12.sp,color=pink,fontWeight=FontWeight.Bold);Spacer(Modifier.height(24.dp));BoardArt(Modifier.fillMaxWidth().aspectRatio(1f));Spacer(Modifier.height(22.dp));Text("Choose your game",fontSize=24.sp,color=ink,fontWeight=FontWeight.ExtraBold);Text("Classic Ludo fun, right on your phone",color=Color.Gray,fontSize=13.sp);Spacer(Modifier.height(18.dp));Mode("PLAY WITH FRIENDS","Local pass & play",pink){play("LOCAL")};Spacer(Modifier.height(12.dp));Mode("PLAY VS COMPUTER","Challenge the CPU",blue){play("COMPUTER")};Spacer(Modifier.height(22.dp));Text("Powered by ZXH OFFICIAL",color=Color.Gray,fontSize=11.sp);Text("ZULQARNAIN X HAIDER",color=Color.LightGray,fontSize=10.sp,fontWeight=FontWeight.Bold)}}
@Composable fun Mode(title:String,sub:String,tint:Color,click:()->Unit){Row(Modifier.fillMaxWidth().height(92.dp).clip(RoundedCornerShape(22.dp)).background(Color.White).border(1.dp,tint.copy(.25f),RoundedCornerShape(22.dp)).clickable{click()}.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(54.dp).clip(RoundedCornerShape(16.dp)).background(tint.copy(.14f)),contentAlignment=Alignment.Center){Text("●",color=tint,fontSize=25.sp)};Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(title,color=ink,fontWeight=FontWeight.ExtraBold);Text(sub,color=Color.Gray,fontSize=12.sp)};Text("›",fontSize=30.sp,color=tint)}}
@Composable fun Setup(mode:String,back:()->Unit,start:()->Unit){Column(Modifier.fillMaxSize().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.fillMaxWidth()){Text("‹ Back",Modifier.clickable{back()},color=pink,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("GAME SETUP",color=ink,fontWeight=FontWeight.ExtraBold)};Spacer(Modifier.height(35.dp));Text(if(mode=="LOCAL")"Local Multiplayer" else "Computer Match",fontSize=27.sp,fontWeight=FontWeight.Black,color=ink);Text("Classic four-colour Ludo",color=Color.Gray);Spacer(Modifier.height(24.dp));BoardArt(Modifier.fillMaxWidth().aspectRatio(1f));Spacer(Modifier.weight(1f));Button(onClick=start,Modifier.fillMaxWidth().height(58.dp),shape=RoundedCornerShape(18.dp)){Text("START GAME",fontWeight=FontWeight.ExtraBold)}}}
@Composable fun Game(dice:Int,turn:Int,moves:Int,roll:()->Unit,move:()->Unit,exit:()->Unit){Column(Modifier.fillMaxSize().padding(14.dp),horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.fillMaxWidth()){Text("‹ EXIT",Modifier.clickable{exit()},color=pink,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("ZXH LUDO",color=ink,fontWeight=FontWeight.Black);Spacer(Modifier.weight(1f));Text("MOVE $moves",color=Color.Gray,fontSize=10.sp)};Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){listOf("RED","GREEN","YELLOW","BLUE").forEachIndexed{i,s->Column(horizontalAlignment=Alignment.CenterHorizontally){Box(Modifier.size(13.dp).clip(CircleShape).background(palette[i]));Text(s,fontSize=9.sp,color=if(i==turn)ink else Color.Gray,fontWeight=FontWeight.Bold)}}};Spacer(Modifier.height(12.dp));BoardArt(Modifier.fillMaxWidth().weight(1f));Text(listOf("RED","GREEN","YELLOW","BLUE")[turn]+" PLAYER'S TURN",color=palette[turn],fontWeight=FontWeight.ExtraBold);Spacer(Modifier.height(10.dp));Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(12.dp)){Box(Modifier.size(58.dp).clip(RoundedCornerShape(14.dp)).background(Color.White).border(2.dp,palette[turn],RoundedCornerShape(14.dp)),contentAlignment=Alignment.Center){Text("$dice",fontSize=30.sp,fontWeight=FontWeight.Black,color=ink)};Button(onClick=roll,modifier=Modifier.height(56.dp)){Text("ROLL DICE")};Button(onClick=move,modifier=Modifier.height(56.dp),colors=ButtonDefaults.buttonColors(containerColor=palette[turn])){Text("MOVE TOKEN")}};Spacer(Modifier.height(14.dp));Text("Native Android • Free • No Ads",color=Color.Gray,fontSize=10.sp)}}
@Composable fun BoardArt(modifier:Modifier=Modifier){Column(modifier.clip(RoundedCornerShape(24.dp)).background(Color.White).border(2.dp,Color(0xFFE9E1F0),RoundedCornerShape(24.dp)).padding(7.dp)){for(r in 0..5){Row(Modifier.weight(1f)){for(c in 0..5){val zone=when{r<3&&c<3->palette[0];r<3&&c>2->palette[1];r>2&&c<3->palette[2];r>2&&c>2->palette[3];else->Color(0xFFF7F3FA)};Box(Modifier.weight(1f).fillMaxHeight().padding(2.dp).clip(RoundedCornerShape(6.dp)).background(if((r==2||r==3)||(c==2||c==3))Color(0xFFF0ECF5)else zone.copy(.16f)),contentAlignment=Alignment.Center){if((r==2||r==3)&&(c==2||c==3))Text("★",color=palette[(r+c)%4],fontSize=17.sp) else if((r<2||r>3)&&(c<2||c>3))Text("●",color=zone,fontSize=16.sp)}}}}}}
